mapper.select:
SELECT f.id, f.owner_id, f.type, f.title, f.content, f.images, f.status, f.handler_id, f.create_time, f.update_time, u.real_name AS owner_name, (SELECT COUNT(*) FROM feedback_reply WHERE feedback_id = f.id) AS reply_count FROM feedback f LEFT JOIN sys_user u ON f.owner_id = u.id
AND f.owner_id = #{ownerId}
AND f.type = #{type}
AND f.status = #{status}
ORDER BY f.create_time DESC
